\section*{Challenge 1: The Hadwiger Conjecture}
\refstepcounter{section}


%Let $G= \ev{V,E}$ be a finite simple graph.
\begin{definition}[Graph Minor] 
Given simple graphs $X$ and $G$, we say that $X$ is a \emph{minor} of $G$ if there is a function assigning to each vertex $x$ of $X$ a nonempty vertex set $V_x\subseteq V(G)$ such that 
\begin{enumerate}
\item the subgraph $G[V_x]$ induced by $G$ on $V_x$ is connected for each $x$;
\item for different vertices  $x,y\in V\ev{X}$, the sets $V_x$ and $V_y$ are disjoint;
\item for any two adjacent vertices $x,y\in V\ev{X}$, there are adjacent vertices $a\in V_x$ and $b\in V_y$ of $G$. 
\end{enumerate}
\end{definition}

%COMMENT FROM NATHAN: maybe we can skip the definitions of minor and chromatic number

\begin{definition}[Hadwiger Number]
Given a graph $G$, the \textit{Hadwiger number} of $G$ is the largest integer $t$ such that the complete graph $K_t$ on $t$ vertices is a minor of $G$.
We denote the Hadwiger number by $h\ev{G}$.
\end{definition}

\begin{definition}[Chromatic number]
Given a graph $G$  and $n\in \mathbb{N}$, 
a \textit{proper coloring} of $G$ with $n$ colours is a function $f:[n] \rightarrow V\ev{G}$ so that adjacent vertices receive different $f$-values. The \textit{chromatic number} of $G$, denoted $\chi\ev{G}$, is the minimum number $n$ such that there is a proper coloring of $G$ with $n$ colours. 
\end{definition}


\begin{conjecture}[Hadwiger's Conjecture
\mbox{\cite[Conjecture 1]{steiner}}]\label{hadw}
Let $r\in \mathbb{N}$.
For every finite simple graph $G$, we have:
$$
r \leq \chi\ev{G} \ \Longrightarrow \  r \leq h\ev{G}
$$ 
\end{conjecture}

\paragraph{Status (October 2026).} Hadwiger's conjecture was disproved in OpenAI's math release (\texttt{github.com/openai/math}; Lean proof checked by Comparator, not yet independently verified). The formal challenge therefore asks for a proof of the \emph{negation} of the universal statement above.

While Conjecture \ref{hadw} is not difficult for values of $r\leq 3$, already for $r=4$ it is equivalent to the 4-colour theorem. 
Robertson, Seymour and Thomas proved the above for $r= 5$ \cite{RobertsonSeymourThomas1993Hadwiger}. 

