\section*{Challenge 10: The Unfriendly Partition Conjecture}
\refstepcounter{section}

(Cowan and Emerson, see for example \cite{aharoni1990unfriendly})

\begin{definition}[Partial and total partition]
A {\em partial partition} of the vertices of a graph $G$ is a function $V(G) \to \{0,1, \ast\}$. We call it {\em finite} if its domain is finite. We call it a {\em total partition} if it is a total function, i.e., $\ast$ is not in the image of $f$. 
\end{definition}

\begin{definition}[Neighbours on a given side]
For a colouring $f$, a vertex $v$, and a colour $b$, the set of \emph{neighbours of $v$ on side $b$} is $\Gamma_b\ev{f} := N(v) \cap f^{-1}\ev{b}$; for a partial partition only the assigned neighbours count.
\end{definition}

\begin{definition}[Unfriendly]
Let $v$ be a vertex of a graph $G$. A partial partition $f$ is {\em unfriendly at $v$} if $v$ is assigned some colour $b := f(v)$ and
$$| \Gamma_{1-b}\ev{f} | \ge | \Gamma_{b}\ev{f} |.$$
A total partition is {\em unfriendly} if it is unfriendly at every vertex.
\end{definition}

\begin{conjecture}[Unfriendly Partition Conjecture]\label{conj:unfriendly}
Every countable graph has an unfriendly partition.
\end{conjecture}

In order to pose a scaled version of this conjecture, we introduce the following game:

\begin{definition}[The $r$-partitioning game.]
Let $r$ be an ordinal number and let $G$ be a graph. The {\em $r$-partitioning game on $G$} is played between two players, Challenger and Partitioner, as follows. A position in the game is a pair $(f, \alpha)$ consisting of a partial partition $f$ of $G$ and an ordinal number $\alpha$. The initial position is $(\emptyset, r)$. In each turn, beginning in position $(f, \alpha)$, Challenger must name a vertex $v$ of $G$ and an ordinal $\beta < \alpha$ and Partitioner must then name a finite partial partition $g$ extending $f$ which is defined at $v$ and unfriendly at $v$. After this, the new position is $(g, \beta)$. If at any point some player is unable to move, the other player wins.
\end{definition}

Note that since there are no infinite decreasing sequences of ordinals this game must end after finitely many turns. 

The scaled conjecture is as follows:

\begin{conjecture}[Scaled Unfriendly Partition Conjecture]
Let $r$ be an ordinal. For any countable graph $G$, Partitioner has a winning strategy in the $r$-partitioning game on $G$.
\end{conjecture}

\paragraph{Formalisation notes.} The formal statement is the Unfriendly Partition Conjecture itself, not its scaled version: a partition is a partial partition defined at every vertex, and the numbers of neighbours on the two sides are compared as cardinals, which matters for vertices of infinite degree. The restriction to countable graphs is essential: Shelah and Milner \cite{ShelahMilner1990} constructed uncountable graphs with no unfriendly partition.

