\section*{Challenge 11: Vizing's Theorem}
\refstepcounter{section}

\begin{definition}[Proper edge-colouring and edge chromatic number]
Let $G$ be a finite graph. A \emph{proper edge-colouring} of $G$ with $k$ colours is a function $c : E\ev{G} \rightarrow [k]$ such that any two edges sharing a common endpoint receive different colours. The \emph{edge chromatic number} $\chi'\ev{G}$ is the least $k$ for which a proper edge-colouring with $k$ colours exists.
\end{definition}

\begin{definition}[Maximum degree]
The \emph{maximum degree} $\Delta\ev{G}$ of $G$ is the largest number of edges incident with any single vertex of $G$.
\end{definition}

\begin{theorem}[Vizing's Theorem \mbox{\cite[Theorem~5.3.2, p.~103]{diestel}}]\label{vizing}
Every finite graph $G$ satisfies
$$
\Delta\ev{G} \ \leq\ \chi'\ev{G} \ \leq\ \Delta\ev{G} + 1 .
$$
\end{theorem}

The lower bound $\Delta\ev{G} \leq \chi'\ev{G}$ is immediate, since the $\Delta\ev{G}$ edges meeting a vertex of maximum degree must all receive distinct colours. The content of the theorem is the upper bound $\chi'\ev{G} \leq \Delta\ev{G} + 1$: every finite graph can be properly edge-coloured with only one colour more than the trivially necessary number.

