\section*{Challenge 15: Ordinary Flats of Given Rank in Complex-Representable Matroids}
\refstepcounter{section}

\begin{definition}[Matroids, flats, and ordinary flats]
A \emph{matroid} $M$ on a finite ground set is a combinatorial abstraction of linear independence, given by a rank function on subsets of the ground set; the \emph{rank} of $M$ is the rank of the whole ground set. A \emph{flat} is a closed set; the rank-$1$ flats are the \emph{points} and the rank-$2$ flats are the \emph{lines}. A line is \emph{ordinary} (a \emph{two-point line}) if it contains exactly two points. More generally, a rank-$k$ flat is \emph{ordinary} if it is the direct sum of a single point with a rank-$(k-1)$ flat --- the higher-rank analogue of an ordinary line.
\end{definition}

\begin{definition}[Complex-representable matroid]
A matroid is \emph{complex-representable} if it arises from a finite family of vectors in a complex vector space, i.e. is representable over $\C$.
\end{definition}

\begin{theorem}[Geelen--Kroeker \mbox{\cite{geelen_matthew}}]\label{ordinaryflat}
For every $k \geq 2$, every complex-representable matroid of rank at least $4(k-1)$ contains an ordinary flat of rank $k$.
\end{theorem}

This is the $\C$-representable instance of a general theorem of Geelen and Kroeker: for any minor-closed class of matroids admitting a two-point line above some fixed rank $C$, every member of rank at least $C(k-1)$ has an ordinary rank-$k$ flat. The constant $4$ here comes from Kelly's theorem, that every complex-representable matroid of rank at least $4$ has a two-point line.

\paragraph{Formalisation notes.} An ordinary flat of rank $k$ is recorded together with its decomposition: a flat $F = P \cup H$ where $P$ is a point and $H$ is a flat with $r(H) = r(F) - 1$, the direct sum condition being that $P \cup H$ is a flat with $r(P \cup H) = r(P) + r(H)$. Complex-representability means that $M$ has a representation in some complex vector space, and $M$ is assumed finite.

