\section*{Challenge 16: Associativity of the Shao Product of Tensors}
\refstepcounter{section}

\begin{definition}[Tensor]
Fix a field $\mathbb{F}$ and a dimension $n$, and write $[n] = \{0, \dots, n-1\}$. An \emph{order-$m$ tensor} over $\mathbb{F}$ is a function $T : [n]^m \rightarrow \mathbb{F}$ assigning a field element to every $m$-tuple of indices from $[n]$ --- equivalently an element of $\mathbb{F}^{n^m}$, an $m$-dimensional array of side $n$.
\end{definition}

\begin{definition}[Shao product]
The \emph{Shao product} $A \odot B$ of an order-$m$ tensor $A$ and an order-$k$ tensor $B$ is the order-$\ev{(m-1)(k-1)+1}$ tensor obtained by a contraction summing over $m-1$ paired index families. For $m = k = 2$ it specialises to ordinary matrix multiplication, and when both factors have order at least $3$ the order of the product strictly exceeds the orders of the factors.
\end{definition}

\begin{theorem}[Associativity of the Shao product \mbox{\cite{shao2013}}]\label{shaoassoc}
Let $A$, $B$, $C$ be tensors of orders $m$, $k$, $l$ respectively, each at least $1$. Then
$$
\ev{A \odot B} \odot C = A \odot \ev{B \odot C} .
$$
Both sides are tensors of order $(m-1)(k-1)(l-1)+1$, and the equality is stated up to the canonical identification of these two equal index arities.
\end{theorem}

\paragraph{Formalisation notes.} Explicitly, for $A$ of order $m$ and $B$ of order $k$, the entry of $A \odot B$ at the index $(i, \alpha_1, \dots, \alpha_{m-1})$ is $\sum_{j_1, \dots, j_{m-1} \in [n]} A_{i j_1 \cdots j_{m-1}} \prod_{r=1}^{m-1} B_{j_r \alpha_r}$, where $\alpha_1, \dots, \alpha_{m-1} \in [n]^{k-1}$ are the consecutive blocks of length $k-1$ into which the last $(m-1)(k-1)$ indices are split.

