\end{thebibliography}

\section*{Challenge 18: Menger's Theorem}
\refstepcounter{section}

\begin{definition}[$S$--$T$ paths and separations]
Let $G$ be a finite graph and $S, T \subseteq V\ev{G}$. An \emph{$S$--$T$ path} is a path with one endpoint in $S$, the other in $T$, and no internal vertex in $S \cup T$. A set $X \subseteq V\ev{G}$ is an \emph{$S$--$T$ separator} (or the order of an \emph{$S$--$T$ separation}) if every $S$--$T$ path meets $X$. Two paths are \emph{vertex-disjoint} if they share no vertex.
\end{definition}

\begin{theorem}[Menger's Theorem, set version \mbox{\cite[Theorem~3.3.1, p.~71]{diestel}}]\label{mengerset}
For any finite graph $G$ and any $S, T \subseteq V\ev{G}$, the maximum number of pairwise vertex-disjoint $S$--$T$ paths equals the minimum order of an $S$--$T$ separator.
\end{theorem}

\begin{theorem}[Menger's Theorem, vertex version]\label{mengervertex}
For distinct, non-adjacent vertices $s, t$ of a finite graph $G$, the maximum number of internally vertex-disjoint $s$--$t$ paths equals the minimum number of vertices (other than $s, t$) whose removal separates $s$ from $t$.
\end{theorem}

The two versions are equivalent; the formal statement is the set version.

\paragraph{Formalisation notes.} In the formal statement the minimum is taken over separations $(A, B)$ of $G$ --- pairs with $A \cup B = V\ev{G}$ and no edge between $A \setminus B$ and $B \setminus A$ --- with $S \subseteq A$ and $T \subseteq B$, the order of $(A, B)$ being $|A \cap B|$. The paths counted are arbitrary paths starting in $S$ and ending in $T$ (possibly a single vertex of $S \cap T$), and disjointness refers to all their vertices.

