\section*{Challenge 19: The Graham--Pollak Theorem}
\refstepcounter{section}

\begin{definition}[Biclique and biclique partition]
A \emph{biclique} of a graph is a complete bipartite subgraph. A \emph{biclique partition} of the complete graph $K_n$ is a family $B_1, \dots, B_m$ of bicliques such that every edge of $K_n$ lies in exactly one $B_i$.
\end{definition}

\begin{theorem}[Graham--Pollak \mbox{\cite{grahampollak}}]\label{grahampollakthm}
If the edge set of the complete graph $K_n$ is partitioned into $m$ bicliques, then $m \geq n - 1$; equivalently $n \leq m + 1$.
\end{theorem}

The bound is tight: the $n-1$ \emph{stars} centred at $n-1$ of the vertices partition $K_n$, so the biclique-partition number of $K_n$ is exactly $n-1$.

