\section*{Challenge 20: Tutte's Wheel Theorem (Deletion/Contraction Reduction)}
\refstepcounter{section}

\begin{definition}[Wheel graph]
The \emph{wheel} $W_n$ ($n \geq 3$) is the graph obtained from a cycle on $n$ vertices (the \emph{rim}) by adding one further vertex (the \emph{hub}) joined to every vertex of the cycle.
\end{definition}

\begin{definition}[$3$-connected reduction edge]
Let $G$ be a finite $3$-connected simple graph and $e$ an edge of $G$. We say $e$ is a \emph{good reduction edge} if the deletion $G - e$ is again $3$-connected, or $e$ lies in no triangle (so that the contraction $G / e$ is again a simple graph) and $G / e$ is $3$-connected.
\end{definition}

\begin{theorem}[Tutte's Wheel Theorem \mbox{\cite{tutte1961}}]\label{tuttewheel}
Every finite $3$-connected simple graph that is not a wheel has a good reduction edge: an edge $e$ such that $G - e$ is $3$-connected, or $G / e$ is a simple $3$-connected graph.
\end{theorem}

This is Tutte's wheel theorem as stated in Oxley's \emph{Matroid Theory} (Theorem 8.8.4). The requirement that $G / e$ be simple cannot be dropped: contracting a rim edge of the wheel $W_n$ ($n \geq 4$) and merging parallel edges gives the $3$-connected graph $W_{n-1}$.

