\section*{Challenge 21: Sidorenko's Conjecture for Half-Graphs}
\refstepcounter{section}

\begin{definition}[Homomorphism density]
For finite simple graphs $H$ and $G$, a \emph{graph homomorphism} $H \rightarrow G$ is a vertex map sending every edge of $H$ to an edge of $G$. Writing $\hom\ev{H,G}$ for the number of such maps, the \emph{homomorphism density} of $H$ in $G$ is
$$
t_H\ev{G} = \frac{\hom\ev{H,G}}{|V\ev{G}|^{\,|V\ev{H}|}} .
$$
\end{definition}

\begin{definition}[Half-graph]
The \emph{half-graph} $H_r$ is the bipartite graph on parts $\{a_1, \dots, a_r\}$ and $\{b_1, \dots, b_r\}$ with an edge $a_i b_j$ exactly when $i \leq j$.
\end{definition}

\begin{conjecture}[Sidorenko's Conjecture \mbox{\cite{sidorenko}}]
For every bipartite graph $H$ and every graph $G$,
$$
t_H\ev{G} \ \geq\ t_{K_2}\ev{G}^{\,|E\ev{H}|} .
$$
\end{conjecture}

\begin{theorem}[Sidorenko for half-graphs]\label{sidorenkohalf}
For every $r$, Sidorenko's inequality holds for the half-graph $H_r$ against every graph $G$:
$$
t_{H_r}\ev{G} \ \geq\ t_{K_2}\ev{G}^{\,|E\ev{H_r}|} .
$$
\end{theorem}

This case is known. The half-graph $H_r$ has a vertex complete to the other side --- the vertex $a_1$ is adjacent to every $b_j$, since $1 \leq j$ --- and Conlon, Fox and Sudakov \cite{conlonfoxsudakov} proved Sidorenko's conjecture for every bipartite graph with a vertex complete to the opposite part. The task is to formalise this known result.

