\section*{Challenge 25: Vertex-transitive graphs of connectivity below five}
\refstepcounter{section}

\begin{definition}[Quasi-$4$-connected]
A finite graph $G$ is \emph{quasi-$4$-connected} (Grohe) if it is $3$-connected and every proper separation $(A,B)$ of $G$ of order at most $3$ has a side that is a single vertex outside the separator (that is, $|A\setminus B|=1$ or $|B\setminus A|=1$).
\end{definition}

\begin{definition}[Cycle-decomposition; cycle of $X$-bags]
A \emph{graph-decomposition} of $G$ modelled on a graph $H$ assigns to each node $h$ of $H$ a bag $V_h\subseteq V(G)$ so that $G=\bigcup_h G[V_h]$ and, for every vertex $v$, the nodes whose bag contains $v$ induce a connected subgraph of $H$~\cite{DJKK}. When $H$ is a cycle $C_\ell$ this is a \emph{cycle-decomposition}. Following~\cite{KurkofkaPlanken} (Definition 2.3), $G$ is a \emph{cycle of $K_4$-bags} (respectively of $C_4$-, $K_{2,2}$- or triangle-bags) if it is quasi-$4$-connected and has a cycle-decomposition whose adhesion-sets $V_i\cap V_j$ have size two, are disjoint (or independent) as specified, and whose bags or torsos are isomorphic to the named graph.
\end{definition}

\begin{theorem}[Kurkofka--Planken~\cite{KurkofkaPlanken}]
A quasi-$4$-connected finite graph $G$ is vertex-transitive if and only if $G$ is one of:
\begin{enumerate}
\item a $(\geq 4)$-regular quasi-$5$-connected vertex-transitive graph;
\item a $3$-regular $2$-quasi-$5$-connected vertex-transitive graph;
\item a $K_4$-expansion, or a vertex-transitive $C_4$-expansion, of a quasi-$5$-connected $4$-regular arc-transitive graph;
\item a cycle of $K_4$-bags of length $\geq 4$;
\item a cycle alternating between $K_4$-bags and $C_4$-bags of length $\geq 4$;
\item a cycle of triangle-bags of length $\geq 6$;
\item a cycle alternating between $K_{2,2}$-bags and $C_4$-torsos of length $\geq 6$;
\item a cycle of $C_4$-bags of length $\geq 4$, or the prism $K_3\,\square\,K_2$;
\item a cycle of $K_{2,2}$-bags of length $\geq 3$, the $K_4$-expansion of one, or a vertex-transitive $C_4$-expansion of one;
\item the line graph of the cube $C_4\,\square\,K_2$, its $K_4$-expansion, or one of its three vertex-transitive $C_4$-expansions.
\end{enumerate}
\end{theorem}

\paragraph{Formalisation notes.} Quasi-$k$-connectivity is formalised as $(k-1)$-connectivity together with the condition that every proper separation of order at most $k-1$ has a side with exactly one vertex outside the separator; $G$ is \emph{$2$-quasi-$5$-connected} if it is quasi-$4$-connected and every proper separation of order at most $4$ has a side with at most two vertices outside the separator. For an $r$-regular graph $G'$ and a graph $H$ on $r$ vertices, an \emph{$H$-expansion} of $G'$ replaces each vertex $v$ of $G'$ by a copy of $H$ on $\{v\}\times V(H)$, realises every edge $uv$ of $G'$ by an edge between the copies of $u$ and $v$, and has every vertex adjacent to at most one vertex outside its own copy (so these edges form a perfect matching); $G$ is an expansion if it is isomorphic to one. The $r$-regularity of $G'$ then implies that every edge $uv$ is realised by exactly one such edge and that there are no edges between the copies of non-adjacent vertices, as in~\cite{KurkofkaPlanken}. The Lean predicates for the cycle-of-bags families do not contain quasi-$4$-connectedness: for $G$ it is the hypothesis of the theorem, and for the base graph of an expansion in item (ix) it is required explicitly. In items (iii) and (ix) a ``vertex-transitive $C_4$-expansion'' means that $G$ itself is vertex-transitive, and in item (x) ``one of its three vertex-transitive $C_4$-expansions'' is stated as ``a vertex-transitive $C_4$-expansion of the line graph of the cube''. Graph-decompositions are those of~\cite[Definition 3.2]{DJKK}, with parts the induced subgraphs $G[V_h]$. The \emph{torso} at a node $i$ of the cycle is $G[V_i]$ with every adhesion-set $V_i\cap V_j$, for $j$ a neighbour of $i$, made complete. In the formal definitions, adhesion-sets on distinct cycle edges are disjoint, except in cycles of triangle-bags, where this is required only for cycle edges without a common endpoint; in cycles alternating between $K_{2,2}$-bags and $C_4$-torsos the adhesion-sets are moreover independent, in cycles of $C_4$-bags each adhesion-set induces a $K_2$, and the $K_{2,2}$-bags of items (vii) and (ix) have $K_4$ torsos.

