\section*{Problem 028: Tutte-type canonical decomposition of 3- and 4-connected graphs (Main Theorem 1)}
\refstepcounter{section}

Throughout, $G$ is a finite simple graph with vertex set $V$. A graph is \emph{$k$-connected} if it has more than $k$ vertices and stays connected after deleting any set of fewer than $k$ vertices.

\begin{definition}[Mixed-separations and tetra-separations]
A \emph{mixed-separation} of $G$ is a pair $\ev{A, B}$ of subsets of $V$ with $A \cup B = V$ and $A \setminus B \neq \emptyset \neq B \setminus A$. Its \emph{separator} $S(A, B)$ is the disjoint union of the vertex set $A \cap B$ and the set $E(A \setminus B, B \setminus A)$ of edges of $G$ with one end in $A \setminus B$ and the other in $B \setminus A$; its \emph{order} is $|S(A, B)|$. A \emph{tetra-separation} of $G$ is a mixed-separation of order $4$ such that every vertex of $A \cap B$ has at least two neighbours in $A \setminus B$ and at least two in $B \setminus A$ (\emph{degree-condition}), and the edges in $S(A, B)$ form a matching (\emph{matching-condition}).
\end{definition}

\begin{definition}[Totally-nested]
Write $\ev{A, B} \leq \ev{C, D}$ if $A \subseteq C$ and $B \supseteq D$. Two pairs $\ev{A, B}$, $\ev{C, D}$ are \emph{nested} if $\ev{A, B} \leq \ev{C, D}$ after possibly exchanging the names $A$ and $B$ or the names $C$ and $D$. A tetra-separation is \emph{totally-nested} if it is nested with every tetra-separation of $G$. Let $N(G)$ be the set of totally-nested tetra-separations of $G$.
\end{definition}

\begin{definition}[Mixed-tree-decompositions]
A \emph{mixed-tree-decomposition} of $G$ is a pair $\mathcal{T} = (T, (V_t)_{t \in T})$ of a tree $T$ and bags $V_t \subseteq V$ such that (M1) every vertex lies in some bag and (M2) for every vertex $v$ the nodes $t$ with $v \in V_t$ induce a connected subgraph of $T$. Every oriented edge $(t_1, t_2)$ of $T$ induces the pair $\alpha(t_1, t_2) = \ev{A_1, A_2}$, where $A_i$ is the union of the bags of the nodes in the component of $T - t_1 t_2$ containing $t_i$. We say that $\mathcal{T}$ is \emph{determined by $N(G)$} if $\alpha$ is a bijection from the set of oriented edges of $T$ onto $N(G)$.
\end{definition}

\begin{definition}[Torsos]
For a pair $\ev{A, B}$ let $\lambda(A, B)$ consist of the vertices of $A \cap B$ and the end in $A \setminus B$ of every edge of $E(A \setminus B, B \setminus A)$. The \emph{expanded-torso} of a node $t$ is obtained from the subgraph of $G$ induced by $V_t \cup \bigcup_{st \in E(T)} \lambda(\alpha(s, t))$ by making each $\lambda(\alpha(s, t))$ into a clique. The \emph{torso} of $t$ is obtained from the expanded-torso by contracting all edges of $G$ that lie in $E(A \setminus B, B \setminus A)$ for some $\ev{A, B} = \alpha(s, t)$ with $st \in E(T)$.
\end{definition}

\begin{definition}[Cycle-decompositions]
Let $X$ and $H$ be graphs. An \emph{$H$-decomposition} of $X$ is a family $(X_h)_{h \in V(H)}$ of subgraphs of $X$ whose union is $X$ (all vertices and edges) such that for every vertex $v$ of $X$ the nodes $h$ with $v \in X_h$ induce a connected subgraph of $H$. It is a \emph{cycle-decomposition} if $H$ is a cycle (of length at least $3$). Its \emph{adhesion-sets} are the sets $V(X_h) \cap V(X_{h'})$ for $hh' \in E(H)$, and the \emph{torso} of a part $X_h$ is obtained from $X_h$ by making each of its adhesion-sets into a clique.
\end{definition}

\begin{definition}[Torso types]
Let $X$ be a graph.
\begin{enumerate}
\item $X$ is \emph{quasi-$5$-connected} if it is $4$-connected and every pair $\ev{A, B}$ with $A \cup B = V(X)$, $A \setminus B \neq \emptyset \neq B \setminus A$, no edge between $A \setminus B$ and $B \setminus A$ and $|A \cap B| = 4$ has $|A \setminus B| = 1$ or $|B \setminus A| = 1$.
\item $X$ is a \emph{cycle of triangle-torsos and $3$-connected torsos on at most $5$ vertices} if $X$ is $4$-connected and has a cycle-decomposition with all adhesion-sets of size $2$ in which every torso is a triangle or a $3$-connected graph on at most $5$ vertices.
\item $X$ is a \emph{generalised double-wheel} with centre $\{u, v\}$ if $X$ is $4$-connected, $u \neq v$, and $X - u - v$ has a cycle-decomposition with all adhesion-sets of size $1$ in which every part is a $K_2$ or a triangle.
\item A \emph{thickened $K_{4,m}$} is obtained from $K_{4,m}$ by turning its left side (of size $4$) into a $K_4$; a \emph{sprinkled $K_{4,m}$} is obtained from $K_{4,m}$ by adding any set of edges inside the left side.
\end{enumerate}
\end{definition}

\begin{theorem}[Kurkofka--Planken~\cite{tuttetypecanonicaldecomposition}, Theorem 1 and Remark 1.2]
Let $G$ be a $4$-connected finite graph. Then $G$ has a mixed-tree-decomposition determined by $N(G)$, and every mixed-tree-decomposition $\mathcal{T}$ of $G$ determined by $N(G)$ satisfies:
\begin{enumerate}
\item[(a)] for every automorphism $\varphi$ of $G$ there is an automorphism $\psi$ of the tree $T$ with $V_{\psi(t)} = \varphi(V_t)$ for every node $t$;
\item[(b)] every torso $\tau$ of $\mathcal{T}$ satisfies one of: (i) $\tau$ is quasi-$5$-connected; (ii) $\tau$ is a cycle of triangle-torsos and $3$-connected torsos on at most $5$ vertices; (iii) $\tau$ is a generalised double-wheel; (iv) $\tau$ is a thickened $K_{4,m}$ for some $m \geq 0$, or $G$ is a sprinkled $K_{4,m}$ for some $m \geq 4$.
\end{enumerate}
\end{theorem}

This is the main result of \cite{tuttetypecanonicaldecomposition}. It lifts Tutte's canonical decomposition of $2$-connected graphs into $3$-connected torsos, cycles and bonds one level up: every $4$-connected graph decomposes canonically along its totally-nested tetra-separations, which may use edges as well as vertices, into quasi-$5$-connected parts, cycles of small torsos, generalised double-wheels and thickened $K_{4,m}$'s. The mixed-tree-decomposition determined by $N(G)$ is unique up to isomorphism of the decomposition trees~\cite{tuttetypecanonicaldecomposition}, so (a) expresses that it is invariant under the automorphisms of $G$.

\paragraph{Formalisation notes.} Only finite graphs are treated (the paper also allows infinite ones). Pairs of vertex sets are \texttt{MixedSep}, sizes are measured with \texttt{Set.encard}, and $E(A \setminus B, B \setminus A)$ is a set of unordered pairs, so the order counts each edge once. A mixed-tree-decomposition is a tree on an arbitrary node type with bags satisfying (M1) and (M2); the separation $\alpha(t_1, t_2)$ is computed from the bags, the component of $T - t_1 t_2$ containing $t_1$ being the set of nodes reachable from $t_1$ in the tree with the edge $t_1 t_2$ deleted. The paper's ``mixed-tree-decomposition uniquely determined by $N(G)$'' is encoded by its defining property, that $\alpha$ is a bijection from the oriented tree edges onto $N(G)$; the statement asserts that such a decomposition exists and then speaks about every such decomposition. Canonicity (Remark 1.2) is stated as automorphism invariance. The torso is built literally: the expanded-torso is a graph on the subtype of its vertex set, and contraction is the quotient by the connected components of the graph of contracted edges, two classes being adjacent when they are distinct and joined by an edge of the expanded-torso. $4$-connectivity is the library notion \texttt{IsVertexConnected}. Cycle-decompositions use the library \texttt{Decomposition} (parts are subgraphs, not necessarily induced) over the cycle graph $C_n$ with $n \geq 3$; in (ii) the paper's ``every torso is isomorphic to some $X_i$'' is spelled out as ``a triangle, or $3$-connected with at most $5$ vertices''. Thickened and sprinkled $K_{4,m}$'s are given by an isomorphism with $K_{4,m}$ on $\mathrm{Fin}\,4 \sqcup \mathrm{Fin}\,m$ plus the edges of $K_4$, respectively of an arbitrary graph, on the left side.

