\section*{Problem 030: Polychromatic colourings for unit-height rectangles (Theorem 26)}
\refstepcounter{section}

\begin{definition}[Range-capturing hypergraph]
A \emph{range family} in $\R^d$ is a collection $R$ of subsets of $\R^d$. A finite point set $V \subseteq \R^d$ is in \emph{general position} if any two distinct points of $V$ differ in every coordinate. For a range family $R$, a finite point set $V$ in general position and an integer $m \geq 1$, the \emph{$m$-uniform range-capturing hypergraph} $H\ev{V, R, m}$ has vertex set $V$, and its hyperedges are the sets $e \subseteq V$ with $|e| = m$ and $e = V \cap \rho$ for some range $\rho \in R$.
\end{definition}

\begin{definition}[Polychromatic colourings and shallow hitting sets]
For an integer $k \geq 1$, a colouring $c \colon V \to \{1, \dots, k\}$ is \emph{polychromatic} for a hypergraph on $V$ if every hyperedge contains a vertex of each colour. Define
$$
m_R(k) := \min\{\, m : H\ev{V, R, m} \text{ is polychromatically } k\text{-colourable for every finite } V \text{ in general position} \,\}.
$$
For an integer $t \geq 1$, a set $X \subseteq V$ is a \emph{$t$-shallow hitting set} of a hypergraph on $V$ if $1 \leq |e \cap X| \leq t$ for every hyperedge $e$.
\end{definition}

\begin{definition}[Unit-height rectangles]
The family $R_{\mathrm{UH}}$ of \emph{unit-height axis-aligned rectangles} in $\R^2$ consists of all sets $[a, b] \times [c, c+1]$ with $a, b, c \in \R$.
\end{definition}

\begin{theorem}[Planken--Ueckerdt~\cite{plankenueckerdt}, Theorem 26]
Let $k \geq 1$.
\begin{enumerate}
\item For every $m \geq 1$ and every finite point set $V \subseteq \R^2$ in general position, the hypergraph $H\ev{V, R_{\mathrm{UH}}, m}$ has a $63$-shallow hitting set.
\item $m_{R_{\mathrm{UH}}}(k) \leq 12k - 7$.
\end{enumerate}
\end{theorem}

This is one of the geometric results of \cite{plankenueckerdt}, which establishes shallow hitting sets of constant size, and hence linear bounds $m_R(k) = O(k)$, for several range families: axis-aligned strips in $\R^d$, bottomless and topless rectangles in $\R^2$, and unit-height rectangles in $\R^2$. Previously only polynomial upper bounds on $m_{R_{\mathrm{UH}}}(k)$ were known.

\paragraph{Formalisation notes.} Points of $\R^2$ have coordinates $(x_0, x_1)$, and a unit-height rectangle is a set $\{x : a \leq x_0 \leq b,\ c \leq x_1 \leq c+1\}$ for reals $a, b, c$ (empty if $a > b$). Every quantification over point sets ranges over finite sets in general position. The parameter $m_R(k)$ is formalised as the infimum of the set of uniformities $m$ at which every $H\ev{V, R, m}$ is polychromatically $k$-colourable, with the convention that the infimum of the empty set is $0$.

