\section*{Problem 031: Shallow hitting sets for axis-aligned strips (Theorem 5)}
\refstepcounter{section}

\begin{definition}[Range-capturing hypergraph]
A \emph{range family} in $\R^d$ is a collection $R$ of subsets of $\R^d$. A finite point set $V \subseteq \R^d$ is in \emph{general position} if any two distinct points of $V$ differ in every coordinate. For a range family $R$, a finite point set $V$ in general position and an integer $m \geq 1$, the \emph{$m$-uniform range-capturing hypergraph} $H\ev{V, R, m}$ has vertex set $V$, and a set $e \subseteq V$ is a hyperedge precisely when $|e| = m$ and $e = V \cap \rho$ for some range $\rho \in R$ (the points of $V$ lying in $\rho$ are exactly those of $e$).
\end{definition}

\begin{definition}[Shallow hitting set]
For an integer $t \geq 0$, a set $X \subseteq V$ is a \emph{$t$-shallow hitting set} of a hypergraph on $V$ if $1 \leq |e \cap X| \leq t$ for every hyperedge $e$, i.e.\ $X$ meets every hyperedge at least once but at most $t$ times.
\end{definition}

\begin{definition}[Axis-aligned strips]
For $d \in \N$, the family $R_{\mathrm{ST}}$ of \emph{axis-aligned strips} in $\R^d$ consists of all sets $\{x \in \R^d : a \leq x_i \leq b\}$ with a coordinate index $i \in \{0, \dots, d-1\}$ and $a, b \in \R$.
\end{definition}

\begin{theorem}[Planken--Ueckerdt~\cite{plankenueckerdt}, Theorem 5]
For every $d \in \N$ there is a constant $t = t(d)$ such that for every integer $m \geq 1$ and every finite point set $V \subseteq \R^d$ in general position, the hypergraph $H\ev{V, R_{\mathrm{ST}}, m}$ has a $t$-shallow hitting set.
\end{theorem}

Planken and Ueckerdt \cite{plankenueckerdt} prove this with $t(d) = 3ed(1+o(1))$. As strips are shrinkable (Problem~34), the reduction lemma of Keszegh and P\'alv\"olgyi \cite{keszeghpalvolgyi} (Problem~29) turns the theorem into the linear bound $m_{R_{\mathrm{ST}}}(k) \leq t(k-1)+1 = O_d(k)$, improving the bound $m_{R_{\mathrm{ST}}}(k) = O_d(k \log k)$ of Aloupis et al.\ \cite{aloupisetal}. Here $m_R(k)$ denotes the least uniformity $m$ such that, for every finite $V$ in general position, $H\ev{V, R, m}$ admits a \emph{polychromatic} $k$-colouring, i.e.\ a colouring of $V$ with $k$ colours in which every hyperedge contains all $k$ colours.

\paragraph{Formalisation notes.} Points of $\R^d$ have coordinates $x_0, \dots, x_{d-1}$, the strip parameters $a, b$ are arbitrary reals (so a strip may be empty), and every quantification over point sets ranges over finite sets in general position. Only the existence of a constant $t$ depending on $d$ alone is required, not the asymptotic value $3ed(1+o(1))$. The hitting set $X$ may be any finite subset of $\R^{d}$; since only the intersections $e \cap X$ with hyperedges $e \subseteq V$ matter, this is equivalent to requiring $X \subseteq V$. The bound $m_{R_{\mathrm{ST}}}(k) \leq t(k-1)+1$ for all $k \geq 1$ is recorded as a corollary, with $m_R(k)$ formalised as the infimum of the uniformities $m$ that work (the infimum of the empty set being $0$).

