\section*{Problem 032: Shallow hitting sets for bottomless rectangles (Theorem 14)}
\refstepcounter{section}

\begin{definition}[Range-capturing hypergraph]
A \emph{range family} in $\R^d$ is a collection $R$ of subsets of $\R^d$. A finite point set $V \subseteq \R^d$ is in \emph{general position} if any two distinct points of $V$ differ in every coordinate. For a range family $R$, a finite point set $V$ in general position and an integer $m \geq 1$, the \emph{$m$-uniform range-capturing hypergraph} $H\ev{V, R, m}$ has vertex set $V$, and a set $e \subseteq V$ is a hyperedge precisely when $|e| = m$ and $e = V \cap \rho$ for some range $\rho \in R$ (the points of $V$ lying in $\rho$ are exactly those of $e$).
\end{definition}

\begin{definition}[Shallow hitting set]
For an integer $t \geq 0$, a set $X \subseteq V$ is a \emph{$t$-shallow hitting set} of a hypergraph on $V$ if $1 \leq |e \cap X| \leq t$ for every hyperedge $e$, i.e.\ $X$ meets every hyperedge at least once but at most $t$ times.
\end{definition}

\begin{definition}[Bottomless rectangles]
The family $R_{\mathrm{BL}}$ of \emph{bottomless rectangles} in $\R^2$ consists of all sets $[a, b] \times (-\infty, c]$ with $a, b, c \in \R$.
\end{definition}

\begin{theorem}[Planken--Ueckerdt~\cite{plankenueckerdt}, Theorem 14]
For every integer $m \geq 1$ and every finite point set $V \subseteq \R^2$ in general position, the hypergraph $H\ev{V, R_{\mathrm{BL}}, m}$ has a $10$-shallow hitting set.
\end{theorem}

As bottomless rectangles are shrinkable (Problem~35), the reduction lemma of Keszegh and P\'alv\"olgyi \cite{keszeghpalvolgyi} (Problem~29) turns the theorem into the linear bound $m_{R_{\mathrm{BL}}}(k) \leq 10(k-1)+1$. Here $m_R(k)$ denotes the least uniformity $m$ such that, for every finite $V$ in general position, $H\ev{V, R, m}$ admits a \emph{polychromatic} $k$-colouring, i.e.\ a colouring of $V$ with $k$ colours in which every hyperedge contains all $k$ colours. For comparison, the bounds $1.67k \leq m_{R_{\mathrm{BL}}}(k) \leq 3k-2$ were known before, by Asinowski et al.\ \cite{asinowskietal}.

\paragraph{Formalisation notes.} Points of $\R^2$ have coordinates $(x_0, x_1)$, and a bottomless rectangle is a set $\{x : a \leq x_0 \leq b,\ x_1 \leq c\}$ for reals $a, b, c$ (empty if $a > b$). Every quantification over point sets ranges over finite sets in general position. The hitting set $X$ may be any finite subset of $\R^{2}$; since only the intersections $e \cap X$ with hyperedges $e \subseteq V$ matter, this is equivalent to requiring $X \subseteq V$. The bound $m_{R_{\mathrm{BL}}}(k) \leq 10(k-1)+1$ for all $k \geq 1$ is recorded as a corollary, with $m_R(k)$ formalised as the infimum of the uniformities $m$ that work (the infimum of the empty set being $0$).

