\section*{Problem 40: A Recolouring Version of a Conjecture of Reed (odd holes and Kempe changes)}
\refstepcounter{section}

All graphs are finite and simple, and colourings are proper colourings with colours $\{1, \dots, k\}$.

\begin{definition}[Local Reed parameter]
For a vertex $v$ of $G$, let $\omega\ev{v}$ be the largest size of a clique of $G$ containing $v$, and $\deg\ev{v}$ its degree. Let $\omega\ev{G}$ be the clique number and $\Delta\ev{G}$ the maximum degree of $G$. Define
$$
f\ev{G} := \max_{v} \left\lceil \frac{\omega\ev{v} + \deg\ev{v} + 1}{2} \right\rceil, \qquad \text{the local analogue of Reed's bound } \left\lceil \frac{\omega\ev{G} + \Delta\ev{G} + 1}{2} \right\rceil.
$$
\end{definition}

\begin{definition}[Kempe changes]
Let $C$ be a $k$-colouring of $G$ and $a, b$ colours. A \emph{Kempe chain} for $\{a, b\}$ is a vertex set $K$ coloured only with $a$ and $b$ that is empty or induces a connected subgraph, and is maximal with this property. The \emph{Kempe change} at $K$ swaps the colours $a$ and $b$ on $K$ and keeps all other colours. Two $k$-colourings are \emph{Kempe equivalent} if one is obtained from the other by finitely many Kempe changes, and $G$ is \emph{$k$-recolourable} if all its $k$-colourings are Kempe equivalent.
\end{definition}

\begin{definition}[Frozen colourings, perfect graphs, odd holes]
A $k$-colouring is \emph{frozen} if any two distinct colour classes together induce a connected subgraph, and it is \emph{unique} if every $k$-colouring is obtained from it by a permutation of the colours. A graph is \emph{perfect} if every induced subgraph has chromatic number equal to its clique number. An \emph{odd hole} is the vertex set of an induced cycle of odd length at least $5$.
\end{definition}

\begin{theorem}[De Meyer--Legrand-Duchesne--Le\'on--Planken--Tamitegama, Theorem 4 \cite{demeyerreedrecolouring}]
\begin{enumerate}
\item[(i)] If every odd hole of $G$ contains a vertex of degree at most $f\ev{G}$, then $G$ is $k$-recolourable for every $k > f\ev{G}$.
\item[(ii)] For every $k \geq 3$ there is a perfect graph $G$ with a frozen $k$-colouring that is not unique, such that $G$ is not $k$-recolourable and $k = \left\lceil \frac{\omega\ev{G} + \Delta\ev{G} + 1}{2} \right\rceil - 1$.
\end{enumerate}
\end{theorem}

Reed's conjecture asserts $\chi\ev{G} \leq \left\lceil \frac{\omega\ev{G} + \Delta\ev{G} + 1}{2} \right\rceil$; the paper \cite{demeyerreedrecolouring} studies the corresponding statement for Kempe recolouring. Part (i) shows that odd-hole-free graphs are $k$-recolourable from $k > f\ev{G}$ on, and part (ii) shows that this is tight up to one colour even for perfect graphs.

\paragraph{Formalisation notes.} The ceilings are computed in $\N$ as $\lceil \frac{m + 1}{2} \rceil = \lfloor \frac{m + 2}{2} \rfloor$. The empty Kempe chain is allowed; it is maximal only for a pair of colours neither of which is used, and the corresponding Kempe change is trivial. An induced cycle of length $n$ is given by an injective map $c \colon \Z/n\Z \to V\ev{G}$ with $c\ev{i}$ adjacent to $c\ev{j}$ if and only if $i - j = \pm 1$. Perfectness compares Mathlib's chromatic number and clique number of every induced subgraph. Both parts are stated together as one conjunction.

