\section*{Problem 41: 3-SAT as an allocation-constraint system}
\refstepcounter{section}

\begin{definition}[3-CNF formulas]
A \emph{literal} over the variables $x_0, \dots, x_{n-1}$ is $x_i$ or $\neg x_i$. A \emph{3-CNF formula} $F$ over these variables is a finite list of clauses, each an ordered triple of literals. $F$ is \emph{satisfiable} if some truth assignment $\tau \colon \{0, \dots, n-1\} \to \{\mathrm{true}, \mathrm{false}\}$ makes at least one literal of every clause true.
\end{definition}

\begin{definition}[Allocation constraints]
An \emph{allocation} of $m$ houses $0, \dots, m-1$ is a map $f \colon \{0, \dots, m-1\} \to \{\mathrm{true}, \mathrm{false}\}$. For a formula $F$ over $n$ variables take $m = 2n$ houses, where house $2i$ carries the literal $x_i$ and house $2i+1$ carries $\neg x_i$. The \emph{NEQ constraints} require $f\ev{2i} \neq f\ev{2i+1}$ for every $i < n$. For every clause $\ev{\ell_1, \ell_2, \ell_3}$ of $F$, the \emph{OR constraint} requires that at least one of the three houses carrying $\ell_1, \ell_2, \ell_3$ has value true.
\end{definition}

\begin{theorem}[Carmesin--Turner, combinatorial step of Lemma 3.2 \cite{carmesinturnertemporal}]
A 3-CNF formula $F$ over $n$ variables is satisfiable if and only if some allocation of the $2n$ houses satisfies all NEQ constraints and all OR constraints of $F$.
\end{theorem}

This is the step of the hardness proof in \cite{carmesinturnertemporal} that is passed over in the paper; there such allocation constraints are realised geometrically by housing sequences, which are not part of this problem.

\paragraph{Formalisation notes.} Clauses are ordered triples of literals and may repeat a literal; the formula has a fixed number $n$ of variables, which may be zero. The OR constraints form the set of triples of houses obtained from the clauses, so repeated clauses give the same constraint.

