\section*{Problem 43: Shallow hitting edge sets in uniform hypergraphs (Theorem 2.4)}
\refstepcounter{section}

\begin{definition}[Finite multihypergraphs]
A \emph{finite multihypergraph} $H$ consists of a finite vertex set $V(H)$, a finite set $E(H)$ of edge labels and, for each label $e$, a support $\operatorname{supp}(e) \subseteq V(H)$; distinct labels may have the same support, so parallel edges are allowed. The \emph{degree} $\deg(v)$ of a vertex $v$ is the number of labels $e \in E(H)$ with $v \in \operatorname{supp}(e)$. For an integer $r$, $H$ is \emph{$r$-uniform} if $|\operatorname{supp}(e)| = r$ for every $e \in E(H)$. For a real number $\mu$, $H$ is \emph{$\mu$-near-regular} if there are integers $\delta, \Delta$ with $\delta > 0$ and $\Delta \leq \mu\delta$ such that $\delta \leq \deg(v) \leq \Delta$ for every vertex $v$.
\end{definition}

\begin{definition}[Shallow hitting edge set]
For an integer $t$, a set $M \subseteq E(H)$ of edge labels is a \emph{$t$-shallow hitting edge set} of $H$ if every vertex $v \in V(H)$ lies in the support of at least one and at most $t$ labels of $M$.
\end{definition}

\begin{theorem}[Planken--Ueckerdt, Theorem 2.4 \cite{shallowhittingedgesets}]\label{shallowedge}
There is a function $t \colon \R \times \N \to \N$ with $t(\mu, r) = \mathrm{e}\mu r\,(1 + o_{\mu r}(1))$, that is,
$$
\frac{t(\mu, r)}{\mathrm{e}\mu r} - 1 \longrightarrow 0 \qquad \text{as } \mu r \to \infty,
$$
such that for every real $\mu > 0$ and every integer $r \geq 1$, every $r$-uniform $\mu$-near-regular finite multihypergraph has a $t(\mu, r)$-shallow hitting edge set. Here $\mathrm{e}$ is Euler's number.
\end{theorem}

This is Theorem 2.4 of \cite{shallowhittingedgesets}. Equivalently, $M$ is a $t$-shallow hitting set (in the sense of Problem 29) of the dual hypergraph, whose vertices are the edge labels of $H$ and whose edges are the vertex stars $\{e : v \in \operatorname{supp}(e)\}$.

\paragraph{Formalisation notes.} The condition $t(\mu, r) = \mathrm{e}\mu r\,(1 + o_{\mu r}(1))$ is formalised as the convergence of $t(\mu, r)/(\mathrm{e}\mu r) - 1$ to $0$ along the filter on $\R \times \N$ generated by the sets $\{(\mu, r) : \mu r \geq a\}$, which is the paper's meaning of $o_{\mu r}(1)$. The function $t$ is chosen before the hypergraph, so a single threshold serves all multihypergraphs. Degrees, uniformity and the hitting condition are counted over edge labels, so parallel edges count with multiplicity.

