\section*{Problem 46: Clustered Haj\'os (Liu--Wood, Theorem 6)}
\refstepcounter{section}

\begin{definition}[Clustered colourings]
Let $G$ be a finite graph and let $k, \eta \geq 0$ be integers. A \emph{$k$-colouring} of $G$ is any map $c \colon V(G) \to \{1, \dots, k\}$; adjacent vertices may receive the same colour. It has \emph{clustering} $\eta$ if, for every colour $a$, every connected component of the subgraph of $G$ induced by $c^{-1}(a)$ has at most $\eta$ vertices.
\end{definition}

\begin{definition}[Subdivisions of complete graphs]
A graph $G$ contains a \emph{subdivision of $K_n$} if there are distinct vertices $b_1, \dots, b_n$ of $G$ (the \emph{branch vertices}) and, for every pair $i < j$, a path $P_{ij}$ in $G$ from $b_i$ to $b_j$, such that no internal vertex of any $P_{ij}$ is a branch vertex and paths of distinct pairs have no internal vertex in common.
\end{definition}

\begin{theorem}[Liu--Wood, Theorem 6 \cite{liuwoodclusteredhajos}]\label{clusteredhajos}
For every integer $s \geq 0$ there is an integer $\eta = \eta(s)$ such that every finite graph that contains no subdivision of $K_{s+1}$ has a $\max(4s - 5, 1)$-colouring with clustering $\eta$.
\end{theorem}

Haj\'os conjectured that every graph containing no subdivision of $K_{s+1}$ is properly $s$-colourable; Catlin disproved this for $s \geq 6$. Theorem~\ref{clusteredhajos}, from \cite{liuwoodclusteredhajos}, shows that for $s \geq 2$ a linear number $4s - 5$ of colours suffices once monochromatic components of bounded size are allowed.

\paragraph{Formalisation notes.} Natural-number subtraction is truncated, so $4s - 5$ is read as $0$ for $s \leq 1$; the maximum with $1$ keeps one colour in these degenerate cases, which lie outside the range $s \geq 2$ treated in the paper. A path $P_{ij}$ is a nonempty list of vertices without repetitions, consecutive vertices being adjacent, that starts at $b_i$ and ends at $b_j$; its internal vertices are its vertices other than $b_i$ and $b_j$. The bound $\eta$ depends on $s$ only.

