\section*{Problem 47: Disproof of the Odd Hadwiger Conjecture (K\"uhn--Sauermann--Steiner--Wigderson, Theorem 1.3)}
\refstepcounter{section}

\begin{definition}[Odd clique minors]
Let $G$ be a graph and $t \geq 0$ an integer. An \emph{odd $K_t$ minor} in $G$ consists of $t$ pairwise vertex-disjoint subgraphs $T_1, \dots, T_t$ of $G$, each of which is a tree, together with a proper $2$-colouring of each $T_i$ (adjacent vertices of $T_i$ receive different colours), such that for all $i \neq j$ there is an edge $xy$ of $G$ with $x \in V(T_i)$, $y \in V(T_j)$ and $x$, $y$ of the same colour.
\end{definition}

\begin{theorem}[K\"uhn--Sauermann--Steiner--Wigderson, Theorem 1.3 \cite{kuhnsauermannsteinerwigdersonoddhadwiger}]\label{oddhadwiger}
For every $\delta > 0$ there is $t_0$ such that for every integer $t \geq t_0$ there is a finite graph $G$ with $\chi(G) \geq (3/2 - \delta)t$ that contains no odd $K_t$ minor.
\end{theorem}

The odd Hadwiger conjecture of Gerards and Seymour (1993) asserts that every graph with no odd $K_t$ minor is properly $(t-1)$-colourable. Theorem~\ref{oddhadwiger}, from \cite{kuhnsauermannsteinerwigdersonoddhadwiger}, disproves it in a strong form: graphs with no odd $K_t$ minor can have chromatic number $(3/2 - o(1))t$.

\paragraph{Formalisation notes.} The definition of an odd minor is the one of \cite{kuhnsauermannsteinerwigdersonoddhadwiger}. Trees are nonempty, and the $2$-colouring of $T_i$ is required to be proper only along the edges of $T_i$. The chromatic bound is stated as $\lceil (3/2 - \delta)t \rceil \leq \chi(G)$, which is equivalent since $\chi(G)$ is an integer. The graph has vertex set $\{0, \dots, n-1\}$ for some $n$.

