\section*{Problem 48: A hypergraph bandwidth theorem (Lang--Sanhueza-Matamala, Theorem 3.5)}
\refstepcounter{section}

Throughout, a \emph{hypergraph} $G$ has a finite vertex set $V(G)$ and a set $E(G)$ of edges, which are subsets of $V(G)$; it is a \emph{$k$-graph} if every edge has exactly $k$ vertices. A \emph{homomorphism} from $H$ to $G$ is a map $\varphi \colon V(H) \to V(G)$ with $\varphi(e) \in E(G)$ for every $e \in E(H)$, and $G$ \emph{contains} $H$ if there is an injective homomorphism from $H$ to $G$. For integers $q \geq t \geq k$ let $C^{k,t}_q$ be the $k$-graph on $\Z_q$ whose edges are the $k$-sets contained in a set $\{a, a+1, \dots, a+t-1\}$ of $t$ cyclically consecutive vertices: $C^{k,k}_q$ is the tight $k$-uniform cycle on $q$ vertices and $C^{k,t}_q$ is its $(t-k+1)$-st power.

\begin{definition}[Connectivity, space and aperiodicity]
Let $G$ be a $k$-graph. Its \emph{line graph} has vertex set $E(G)$, two distinct edges being adjacent if they share exactly $k - 1$ vertices. $G$ is \emph{connected} if every vertex lies in an edge and the line graph is connected (in particular $E(G) \neq \emptyset$). A \emph{component} of $G$ is a connected subgraph $F$ with $V(F) = V(G)$ whose edge set is maximal among such subgraphs. A \emph{fractional matching} of $G$ is a function $\omega \colon E(G) \to [0, 1]$ with $\sum_{e \ni v} \omega(e) \leq 1$ for every vertex $v$; it is \emph{perfect} if $\sum_{e} \omega(e) = |V(G)|/k$. A \emph{closed walk} of order $q \geq k$ in $G$ is a homomorphism from $C^{k,k}_q$ to $G$, and $G$ is \emph{aperiodic} if it has a closed walk of some order $q \equiv 1 \pmod{k}$.
\end{definition}

\begin{definition}[Hamilton framework]
Let $\mathcal P$ be a family of $t$-graphs on the vertex set $[s] = \{1, \dots, s\}$. A \emph{Hamilton framework} for $\mathcal P$ assigns to every $G \in \mathcal P$ a subgraph $F(G)$ of $G$ such that
\begin{itemize}
\item[(F1)] $F(G)$ is a component of $G$;
\item[(F2)] $F(G)$ has a perfect fractional matching;
\item[(F3)] $F(G)$ is aperiodic;
\item[(F4)] whenever $J$ is a hypergraph on $s + 1$ vertices, $x \neq y$ are vertices of $J$, and $G, G' \in \mathcal P$ are isomorphic to $J - x$ and $J - y$, the union of the copies of $F(G)$ and $F(G')$ in $J$ is connected.
\end{itemize}
\end{definition}

\begin{definition}[Clique graph, property graph and robustness]
Let $G$ be a $k$-graph on $n$ vertices and $t \geq k$. The \emph{clique graph} $K_t(G)$ is the $t$-graph on $V(G)$ whose edges are the $t$-sets $S \subseteq V(G)$ all of whose $k$-subsets are edges of $G$. For a $t$-graph $G'$ on $V(G)$ and a family $\mathcal P$ of $t$-graphs on $[s]$, the \emph{property graph} $P^{(s)}(G', \mathcal P)$ is the $s$-graph on $V(G)$ whose edges are the $s$-sets $S$ for which the induced subgraph $G'[S]$ is isomorphic to a member of $\mathcal P$. Finally, $G'$ \emph{$s$-robustly satisfies} $\mathcal P$ if every set of $2t$ vertices lies in at least $(1 - 1/s^2)\binom{n - 2t}{s - 2t}$ edges of $P^{(s)}(G', \mathcal P)$.
\end{definition}

\begin{definition}[Blow-ups]
Let $q \geq t$. A $k$-graph $H$ is a \emph{blow-up} of $C^{k,t}_q$ with clusters of size at most $m$ if there is a surjection $\pi \colon V(H) \to \Z_q$ such that a set $e \subseteq V(H)$ is an edge of $H$ if and only if $|e| = k$ and $\pi(e)$ is an edge of $C^{k,t}_q$, and every cluster $\pi^{-1}(i)$ has at most $m$ vertices.
\end{definition}

\begin{theorem}[Lang--Sanhueza-Matamala, Theorem 3.5 \cite{langsanhuezamatamalabandwidth}]\label{bandwidth}
For all integers $k, t, s$ with $2 \leq k \leq t$ and $2t \leq s$ there are $c > 0$ and $n_0$ such that the following holds. Let $\mathcal P$ be a family of $t$-graphs on $[s]$ that admits a Hamilton framework, and let $G$ be a $k$-graph on $n \geq n_0$ vertices such that $K_t(G)$ $s$-robustly satisfies $\mathcal P$. Then $G$ contains every $n$-vertex blow-up of $C^{k,t}_q$ ($q \geq t$) with clusters of size at most $(\log\log n)^c$.
\end{theorem}

This is the general hypergraph bandwidth theorem of \cite{langsanhuezamatamalabandwidth}, extending the Bandwidth Theorem of B\"ottcher, Schacht and Taraz from graphs to hypergraphs; the paper derives from it blown-up versions of Dirac-type Hamiltonicity results for hypergraphs.

\paragraph{Formalisation notes.} The members of $\mathcal P$ are labelled $t$-graphs on $[s]$, and the isomorphisms in the property graph and in (F4) are explicit bijections; (F4) is required for every choice of these bijections. Fractional matchings are functions on all vertex subsets that vanish off the edge set. The parameter range $2 \leq k \leq t$, $2t \leq s$ is assumed explicitly. The vertex sets of $G$ and $H$ are finite types of the same size $n$, so the copy of $H$ in $G$ is spanning. Logarithms are natural.

