\section*{Problem 49: Counting perfect matchings in Dirac hypergraphs (Kwan--Safavi--Wang, Theorem 1.7)}
\refstepcounter{section}

\begin{definition}[Minimum degrees and Dirac thresholds]
A \emph{$k$-uniform hypergraph} (\emph{$k$-graph}) $G$ on a finite vertex set $V$ is a set of $k$-element subsets of $V$, its \emph{edges}. For $0 \le d < k$, the \emph{degree} of a set $S \subseteq V$ is the number of edges containing $S$, and the \emph{minimum $d$-degree} $\delta_d(G)$ is the least degree of a $d$-element subset of $V$. A \emph{perfect matching} is a set of pairwise disjoint edges whose union is $V$, and $\Phi(G)$ denotes the number of perfect matchings of $G$. For $k \mid n$, the \emph{Dirac threshold} $m_d(k,n)$ is the least integer $m$ such that every $k$-graph on $n$ vertices with $\delta_d(G) \ge m$ has a perfect matching, and the \emph{asymptotic Dirac threshold} is
$$\alpha_d(k) = \lim_{n \to \infty,\ k \mid n} \frac{m_d(k,n)}{\binom{n-d}{k-d}}.$$
\end{definition}

\begin{definition}[Fractional perfect matchings and entropy]
A \emph{fractional perfect matching} of $G$ is a weighting $x \colon E(G) \to [0,1]$ with $\sum_{e \ni v} x[e] = 1$ for every vertex $v$. Its \emph{entropy} is $h(x) = \sum_{e \in E(G)} x[e] \ln(1/x[e])$, with the convention $0 \ln(1/0) = 0$, and the \emph{entropy} of $G$ is $h(G) = \sup_x h(x)$, the supremum over all fractional perfect matchings $x$ of $G$.
\end{definition}

\begin{theorem}[Kwan--Safavi--Wang, Theorem 1.7 \cite{kwansafaviwangcountingmatchings}]
Fix integers $1 \le d < k$ and a real number $\gamma > 0$. Let $G$ be a $k$-graph on $n$ vertices, $k \mid n$, with $\delta_d(G) \ge (\alpha_d(k) + \gamma)\binom{n-d}{k-d}$. Then the number of perfect matchings of $G$ is
$$\Phi(G) = e^{h(G)} \bigl(1/e + o(1)\bigr)^{(1-1/k)n},$$
where the asymptotics are as $n \to \infty$ along integers divisible by $k$.
\end{theorem}

This extends to hypergraphs the theorem of Cuckler and Kahn \cite{cucklerkahnentropy} on the number of perfect matchings in graphs of minimum degree at least $n/2$. The limit $\alpha_d(k)$ exists by a theorem of Ferber and Kwan \cite{ferberkwandirac}, but its value is unknown for most pairs $(d,k)$.

\paragraph{Formalisation notes.} The vertex set is $\{0, \dots, n-1\}$ with $n = km$, and the theorem is stated for every family $(G_m)_{m \ge 0}$ of $k$-graphs on $km$ vertices that satisfies the degree condition for all large $m$; this is equivalent to the uniform $o(1)$ above. The conclusion is the logarithmic form $\bigl(\ln \Phi(G_m) - h(G_m) + (1-1/k)n\bigr)/n \to 0$. The asymptotic threshold enters as a real number $\alpha$ together with the hypothesis $m_d(k,km)/\binom{km-d}{k-d} \to \alpha$ as $m \to \infty$, where $m_d(k,n)$ is the infimum of the degree bounds that force a perfect matching. The minimum $d$-degree is computed with the number of edges as an extra candidate value, so that it is defined even when there is no $d$-element set; otherwise it equals $\delta_d(G)$. Fractional perfect matchings are weightings of all vertex subsets that vanish off the edges, and $h(G)$ is the supremum of their entropies.

