\section*{Problem 50: Dirac's theorem for linear hypergraphs (Im--Lee, Theorem 1.2)}
\refstepcounter{section}

\begin{definition}[Linear hypergraphs and matchings]
A \emph{$k$-uniform hypergraph} (\emph{$k$-graph}) $H$ on a finite vertex set $V$ is a set of $k$-element subsets of $V$, its \emph{edges}. It is \emph{linear} if any two distinct edges share at most one vertex. The \emph{degree} of a vertex is the number of edges containing it, and $\delta(H)$ is the minimum degree. A \emph{matching} is a set of pairwise disjoint edges; it \emph{covers} the vertices in the union of its edges.
\end{definition}

\begin{theorem}[Im--Lee, Theorem 1.2 \cite{imleediraclinear}]
For every $\varepsilon > 0$ and every integer $k \ge 2$ there exist positive integers $C = C(\varepsilon,k)$ and $n_0 = n_0(\varepsilon,k)$ such that the following holds for all $n \ge n_0$. Every linear $k$-graph $H$ on $n$ vertices with $\delta(H) \ge n/k + C$ contains a matching that covers at least $(1-\varepsilon)n$ vertices.
\end{theorem}

For $k = 2$ every graph is linear and the statement follows from Dirac's theorem. The degree condition is asymptotically best possible for every $k \ge 2$, by a construction from mutually orthogonal Latin squares (Proposition 1.3 of \cite{imleediraclinear}).

\paragraph{Formalisation notes.} The vertex set is $\{0, \dots, n-1\}$, and every element of it is a vertex of $H$. The minimum degree is computed with the number of edges as an extra candidate value, so that it is defined for every $n$; for $n \ge 1$ it equals $\delta(H)$, and the statement only concerns $n \ge n_0 \ge 1$.

