\section*{Problem 53: Hypergraph joints (Chao--Yu, Theorem 1.12)}
\refstepcounter{section}

\begin{definition}[Coloured hypergraphs and covering weights]
Let $H = ([d], E, c)$ be a hypergraph on the vertex set $[d] = \{1, \dots, d\}$ whose edge set $E$ may be a multiset, with an edge colouring $c \colon E \to [r]$. For integers $1 \le k_1, \dots, k_r \le d-1$, the colouring is \emph{$(d-k_1, \dots, d-k_r)$-uniform} if for every colour $i$ the class $c^{-1}(i)$ is a nonempty simple hypergraph all of whose edges have $d - k_i$ vertices. A weight function $w \colon E \to \R_{\ge 0}$ \emph{covers} $H$ if $\sum_{e \ni j} w(e) \ge 1$ for every $j \in [d]$. Write $|w| = \sum_{e \in E} w(e)$ and $\bar w_i = \sum_{e \in c^{-1}(i)} w(e)$.
\end{definition}

\begin{definition}[$H$-joints]
Let $\mathbb{F}$ be a field and, for each colour $i$, let $\mathcal{F}_i$ be a finite multiset of $k_i$-dimensional affine subspaces ($k_i$-flats) of $\mathbb{F}^d$. A point $p \in \mathbb{F}^d$ is an \emph{$H$-joint} if there are flats $F_{p,e} \in \mathcal{F}_{c(e)}$, one for each $e \in E$, and an invertible affine map $A \colon \mathbb{F}^d \to \mathbb{F}^d$ with $A(0) = p$ and $F_{p,e} = A\bigl(\mathrm{span}\{\vec e_j : j \notin e\}\bigr)$ for every $e \in E$, where $\vec e_j$ is the $j$-th unit vector. Let $\mathcal{J}$ be the set of $H$-joints, counted without multiplicity.
\end{definition}

\begin{theorem}[Chao--Yu, Theorem 1.12 \cite{chaoyuhypergraphjoints}]
Let $H = ([d], E, c)$ be $(d-k_1, \dots, d-k_r)$-uniformly edge-coloured with $1 \le k_i \le d-1$, let $w$ be a weight function covering $H$, and let $\mathcal{F}_1, \dots, \mathcal{F}_r$ be finite multisets of $k_1, \dots, k_r$-flats in $\mathbb{F}^d$. Then
$$|\mathcal{J}| \le C_{H,w}\, |\mathcal{F}_1|^{\bar w_1} \cdots |\mathcal{F}_r|^{\bar w_r}, \qquad C_{H,w} = d!^{\,|w|-1} \prod_{i=1}^{r} \Bigl(\frac{1}{k_i!}\Bigr)^{\bar w_i} \prod_{e \in E} \Bigl(\frac{w(e)}{\bar w_{c(e)}}\Bigr)^{w(e)},$$
with the convention $\bigl(w(e)/\bar w_{c(e)}\bigr)^{w(e)} = 1$ when $w(e) = 0$, even if $\bar w_{c(e)} = 0$.
\end{theorem}

When $H$ consists of all $(d-1)$-subsets of $[d]$ in a single colour, so that $k_1 = 1$, an $H$-joint is a joint of lines in the usual sense: $d$ lines through $p$ with linearly independent directions (Example 1.9 of \cite{chaoyuhypergraphjoints}). As shown in \cite{chaoyuhypergraphjoints}, the theorem implies a partial shadow phenomenon for every hypergraph, generalising the theorem of Friedgut and Kahn on the maximum number of copies of a fixed hypergraph in a hypergraph with a given number of edges.

\paragraph{Formalisation notes.} The edges of $H$ are indexed by $\{0, \dots, |E|-1\}$, so repeated edges are allowed, and each $\mathcal{F}_i$ is an indexed finite family of flats, so $|\mathcal{F}_i|$ counts multiplicity. A flat is given by a base point and a direction subspace of dimension $k_i$. The affine map is written $A(x) = p + L(x)$ with $L$ a linear automorphism of $\mathbb{F}^d$, and the condition on $F_{p,e}$ says that $F_{p,e}$ contains $p$ and has direction $L(\mathrm{span}\{\vec e_j : j \notin e\})$. A configuration lists a finite set of points that is exactly the set of $H$-joints. Powers are real powers with $x^0 = 1$ for every $x$, including $x = 0$, and $w(e)/\bar w_{c(e)} = 0$ when $\bar w_{c(e)} = 0$, which implements the convention above.

