\section*{Problem 58: Brill--Noether Existence for Finite Graphs}
\refstepcounter{section}

\begin{definition}[Divisors on a graph]
Let $G$ be a finite connected multigraph without loops, with vertex set $V$ and $\lvert E\rvert$ edges, and let $g = \lvert E\rvert - \lvert V\rvert + 1$ be its \emph{genus} (cycle rank). A \emph{divisor} on $G$ is a function $D \colon V \to \Z$; its \emph{degree} is $\deg D = \sum_{v \in V} D\ev{v}$, and $D$ is \emph{effective} if $D\ev{v} \geq 0$ for every $v$. \emph{Firing} a vertex $v$ sends one chip along each edge at $v$: it lowers $D\ev{v}$ by the degree of $v$ and raises $D\ev{w}$ by the number of edges between $v$ and $w$, for every $w \neq v$. Two divisors $D$ and $D'$ are \emph{linearly equivalent}, written $D \sim D'$, if $D' - D$ lies in the subgroup of $\Z^V$ generated by these firing vectors.
\end{definition}

\begin{definition}[Rank and the Brill--Noether number]
A divisor $D$ has \emph{rank at least $r$} if for every effective divisor $A$ of degree $r$ the divisor $D - A$ is linearly equivalent to an effective divisor. It has \emph{rank exactly $r$} if it has rank at least $r$ but not rank at least $r + 1$. For integers $g, r, d$ the \emph{Brill--Noether number} is
$$
\rho\ev{g, r, d} = g - \ev{r+1}\ev{g - d + r}.
$$
\end{definition}

\begin{openproblem}[Baker's Brill--Noether existence conjecture]
Prove or disprove: for all integers $r, d \geq 0$ with $\rho\ev{g, r, d} \geq 0$, every finite connected loopless multigraph of genus $g$ has a divisor $D$ of rank exactly $r$ with $\deg D \leq d$.
\end{openproblem}

This is the existence part of Conjecture~3.9 of \cite{Baker2008Specialization}, the graph analogue of the classical Brill--Noether existence theorem for algebraic curves. Atanasov and Ranganathan proved it for $g \leq 5$ \cite{AtanasovRanganathan2018LowGenus}; it is open in general. The case $r = 1$ is the gonality conjecture (Problem~57), and the analogous statement for metric graphs is a theorem of Baker (see Problem~59).

\paragraph{Formalisation notes.} The definitions follow the Lean chip-firing development of Mavani and Pflueger \cite{MavaniPflueger2026ChipFiringLean}, rebased on the multigraph type of Problems~54--56: edges are indexed by a finite type (so parallel edges are allowed), loops are excluded, there is at least one vertex, and connectivity is that of the underlying simple graph. The genus is computed in $\Z$. The rank is not a function but the relation ``rank at least $r$'' defined above, and ``rank exactly $r$'' is defined from it. The form ``rank exactly $r$ and degree at most $d$'' is the one used in \cite{AtanasovRanganathan2018LowGenus}; it is equivalent to the more common ``rank at least $r$ and degree exactly $d$''.

