\section*{Problem 59: Combinatorial Brill--Noether Existence for Metric Graphs}
\refstepcounter{section}

\begin{definition}[Metric graphs and their divisors]
A \emph{metric graph} $\Gamma$ is given by a finite connected multigraph $G$ without loops, with vertex set $V$ and $\lvert E\rvert$ edges, together with a length $\ell\ev{e} > 0$ for every edge $e$; each edge is a real interval $[0, \ell\ev{e}]$ glued to the graph at its two ends. The \emph{points} of $\Gamma$ are the vertices and the interior points of the edges, and its \emph{genus} is $g = \lvert E\rvert - \lvert V\rvert + 1$. A \emph{divisor} on $\Gamma$ is a finitely supported function $D$ from the points of $\Gamma$ to $\Z$; its \emph{degree} is $\deg D = \sum_p D\ev{p}$, and $D$ is \emph{effective} if $D\ev{p} \geq 0$ for every point $p$.
\end{definition}

\begin{definition}[Rational functions and linear equivalence]
A \emph{rational function} on $\Gamma$ is a continuous function $f \colon \Gamma \to \R$ that is piecewise affine with integer slopes on every edge, with finitely many breakpoints. Its \emph{divisor} $\ev{f}$ assigns to each point $p$ minus the sum of the outgoing slopes of $f$ at $p$. Two divisors $D$ and $D'$ are \emph{linearly equivalent}, written $D \sim D'$, if $D' - D$ lies in the subgroup generated by the divisors of rational functions.
\end{definition}

\begin{definition}[Rank and the Brill--Noether number]
A divisor $D$ has \emph{rank at least $r$} if for every effective divisor $A$ of degree $r$ on $\Gamma$ the divisor $D - A$ is linearly equivalent to an effective divisor. It has \emph{rank exactly $r$} if it has rank at least $r$ but not rank at least $r + 1$. For integers $g, r, d$ the \emph{Brill--Noether number} is
$$
\rho\ev{g, r, d} = g - \ev{r+1}\ev{g - d + r}.
$$
\end{definition}

\begin{theorem}[Brill--Noether existence for metric graphs]
Let $r, d \geq 0$ be integers with $\rho\ev{g, r, d} \geq 0$. Then every metric graph of genus $g$ has a divisor $D$ of rank exactly $r$ with $\deg D \leq d$.
\end{theorem}

This theorem is due to Baker \cite{Baker2008Specialization}. His proof relies on algebraic geometry, and he asked for a purely combinatorial proof. Combinatorial arguments are known for genus at most five \cite{AtanasovRanganathan2018LowGenus} and in rank one \cite{DraismaVargas2021Catalan}. The corresponding statement for finite graphs is open (Problems~57 and~58).

\paragraph{Formalisation notes.} A metric graph is given by a fixed loopless model with positive real edge lengths; every compact connected metric graph has such a model, and the genus does not depend on the model. Connectivity is that of the underlying simple graph. Each edge is parametrised by $[0, \ell\ev{e}]$ from one of its ends, and its interior points are the reals in the open interval $\ev{0, \ell\ev{e}}$. A rational function is recorded edgewise by its values and its one-sided integer slopes, which must make it affine on a one-sided neighbourhood of every point and continuous at the vertices; the requirements that its divisor have finite support and degree zero are included as conditions, and they hold automatically for such functions. The sign convention for $\ev{f}$ does not affect linear equivalence. As in Problem~58, ``rank at least $r$'' is a relation and ``rank exactly $r$'' is defined from it; the effective divisors $A$ range over all points of $\Gamma$, not only vertices.

