\section*{Problem 69: Algebraic Connectivity of Token Graphs}
\refstepcounter{section}

\begin{definition}[Algebraic connectivity]
Let $G$ be a finite simple graph on $n$ vertices with Laplacian matrix $L\ev{G} = D - A$, where $D$ is the diagonal matrix of degrees and $A$ the adjacency matrix. Its eigenvalues, listed with multiplicity, are $0 = \lambda_1 \le \lambda_2 \le \dots \le \lambda_n$. For $n \ge 2$ the \emph{algebraic connectivity} of $G$ is $a\ev{G} = \lambda_2$, the second-smallest eigenvalue.
\end{definition}

\begin{definition}[Token graphs]
For an integer $k \ge 0$, the \emph{$k$-token graph} $F_k\ev{G}$ has as vertices the $k$-element subsets of $V\ev{G}$ (placements of $k$ indistinguishable tokens on distinct vertices). Two such sets $A$ and $B$ are adjacent when $B = \ev{A \setminus \{u\}} \cup \{v\}$ for an edge $uv$ of $G$ with $u \in A$ and $v \notin A$, that is, when one token moves along an edge of $G$ to an unoccupied vertex.
\end{definition}

\begin{theorem}[Algebraic connectivity of token graphs]
Let $G$ be a finite simple graph on $n$ vertices and let $1 \le k < n$. Then $a\ev{F_k\ev{G}} = a\ev{G}$.
\end{theorem}

The equality was conjectured by Dalf\'o et al.\ \cite{DalfoEtAl2021TokenSpectra} and studied further by Song, Dalf\'o, Fiol and Zhang \cite{SongEtAl2025TokenConnectivity}. It is also a consequence of Caputo, Liggett and Richthammer's proof of Aldous' spectral gap conjecture \cite{CaputoLiggettRichthammer2010}; a direct combinatorial or algebraic proof is not known.

\paragraph{Formalisation notes.} The graph $G$ need not be connected. Eigenvalues are Mathlib's ordered eigenvalues of the real symmetric Laplacian, counted with multiplicity, so repeated zero eigenvalues of disconnected graphs are represented faithfully. The algebraic connectivity is defined to be $0$ for graphs with fewer than two vertices; this value is never used, since $1 \le k < n$ forces $n \ge 2$ and $F_k\ev{G}$ has $\binom{n}{k} \ge 2$ vertices.

