\section*{Problem 71: Bipartite Unique-Neighbour Expanders via Ramanujan Graphs}
\refstepcounter{section}

\begin{definition}[Bipartite multigraphs and unique neighbours]
A finite \emph{bipartite multigraph} $G$ has a left side $L$, a right side $R$ and, for every $u \in L$ and $v \in R$, a number $m\ev{u, v} \ge 0$ of parallel edges between $u$ and $v$. It is \emph{$\ev{c, d}$-biregular} if every left vertex has degree $c$ and every right vertex has degree $d$, parallel edges counted. For a set $S \subseteq L$, its neighbourhood $N\ev{S}$ is the set of right vertices joined to at least one vertex of $S$, and a right vertex $v$ is a \emph{unique neighbour} of $S$ if exactly one vertex of $S$ is joined to $v$.
\end{definition}

\begin{definition}[Unique-neighbour expander family]
A sequence $\ev{G_n}_{n \in \N}$ of $\ev{c, d}$-biregular bipartite multigraphs with sides $L_n, R_n$ is a \emph{unique-neighbour expander family} if $|L_n| + |R_n| \to \infty$ and there is $\delta > 0$ such that for every $n$, every nonempty $S \subseteq L_n$ with $|S| \le \delta |L_n|$ has a unique neighbour in $G_n$.
\end{definition}

\begin{theorem}[Asherov--Dinur, Theorem 1, existence form]
There is a function $\hat q \colon \N \times \R \to \N$ such that for every integer $c_0 > 5$, every real $\alpha > 1$ and every prime power $q > \hat q\ev{c_0, \alpha}$ for which $\alpha c_0 \ev{q + 1}$ is an integer, there is a $\ev{c_0 \ev{q+1}, \alpha c_0 \ev{q+1}}$-biregular unique-neighbour expander family.
\end{theorem}

This is Theorem 1 of Asherov and Dinur \cite{asherovdinur2023unique}, who construct such families in polynomial time from the biregular Ramanujan graphs of Ballantine et al.\ \cite{ballantine2015ramanujan}. Since $c|L_n| = d|R_n|$, the ratio $|R_n|/|L_n| = 1/\alpha$ can be made arbitrarily small. Explicit unique-neighbour expanders were first constructed by Alon and Capalbo \cite{aloncapalbo2002unique}.

\paragraph{Formalisation notes.} The clause ``constructed in polynomial time'' of Theorem 1 is not formalised, as it concerns a model of computation; only the existence of the family is asserted, with the paper's degree parameters. The condition that $\alpha c_0 \ev{q+1}$ is an integer is expressed by quantifying over natural numbers $d$ with $d = \alpha c_0 \ev{q+1}$. Parallel edges are allowed, as in Section 3.1 of \cite{asherovdinur2023unique}; degrees count them, while neighbourhoods and unique neighbours depend only on which pairs are joined. The sides of $G_n$ are $\{0, \dots, |L_n| - 1\}$ and $\{0, \dots, |R_n| - 1\}$. The proof in Section 6.2 of \cite{asherovdinur2023unique} uses a gadget with $\ev{q^3+1}/\ew{\alpha\ev{q+1}}$ right vertices and so tacitly needs this number to be an integer; the printed statement of Theorem 1 has no such proviso, and it is formalised as printed.

