\section*{Challenge 96: Characteristic and Matching Polynomials of a Uniform Hypertree}
\refstepcounter{section}

\begin{definition}[Hypertrees, matching polynomial, boundary]
An $r$-uniform hypergraph is a finite family of $r$-element edges; an \emph{$r$-tree} is obtained from a single edge by repeatedly attaching a new edge sharing exactly one vertex with the existing hypergraph. The \emph{matching polynomial} of an $r$-uniform hypergraph $H$ on $n$ vertices is $\varphi_H(\lambda) = \sum_k (-1)^k m_k(H)\,\lambda^{\,n - rk}$ where $m_k$ counts $k$-matchings. For a subgraph $H$ of $T$, the \emph{boundary} $\partial H$ is the set of edges of $T$ not in $H$ that meet $H$. The characteristic polynomial $\varphi_T$ of the adjacency tensor is defined through the resultant of the eigenvalue system, represented in Lean by polynomial division of the two Macaulay determinants. The edge-set model here treats hypertrees with at least one edge.
\end{definition}

\begin{theorem}[Li--Su--Fallat, Theorem 4.10 \cite{li2023hypertree}]\label{hypertree}
Let $T$ be an $r$-tree with $m$ edges, $r \ge 2$, $b = (r-1)^{r-1}$, $c = r^{r-2}$. Then
$$\varphi_T(\lambda) = \prod_{H} \varphi_H(\lambda)^{a_H}, \qquad a_H = b^{\,m - e(H) - |\partial H|}\, c^{\,e(H)}\, (b - c)^{|\partial H|},$$
the product over the connected subgraphs $H$ of $T$, single vertices included (with $\varphi = \lambda$ and boundary the star of the vertex).
\end{theorem}

For $r = 2$ the exponents collapse and the identity is the classical fact that the characteristic and matching polynomials of a tree coincide.

\paragraph{Formalisation notes.} Vertices are natural numbers, a hypergraph is given by its edge set, and $r$-trees are described inductively by the coalescence construction above. The boundary $\partial H$ is formalised as the set of edges of $T$ meeting both $V(H)$ and $V(T) \setminus V(H)$. The characteristic polynomial is defined through the Macaulay formula $\operatorname{Res} = D_n / D'_n$ of \cite[Proposition 2.3]{li2023hypertree}. For the eigenvalue system $\lambda x_i^{r-1} = \sum_{e \ni i} x^{e \setminus \{i\}}$, the Macaulay matrix in the monomials $x^\alpha$ of total degree $d = n(r-2)+1$ is $\lambda I - C$, where $C$ is the $0/1$ transfer matrix sending $\alpha$ to $\alpha - (r-1)\mathbf{1}_i + \mathbf{1}_{e \setminus \{i\}}$ for every edge $e \ni i$, with $i$ the class of $\alpha$ (the least vertex with $\alpha_i \ge r-1$, which exists by pigeonhole); thus $D_n = \det(\lambda I - C)$ and $D'_n = \det(\lambda I - C')$, with $C'$ the restriction of $C$ to the non-reduced monomials (those with at least two vertices $i$ with $\alpha_i \ge r-1$). Since $D'_n$ is monic, the quotient of $D_n$ by $D'_n$ under polynomial division is always defined; that this quotient is the resultant, i.e.\ that the division is exact, is the content of Proposition 2.3 and is not part of the formal definition.

