\section*{Challenge 99: Colouring the 1-Skeleton of d-Dimensional Triangulations}
\refstepcounter{section}

\begin{definition}[Triangulations, subdivisions]
A \emph{combinatorial $d$-sphere} is, for $d = 0$, a pair of distinct points and, for $d \ge 1$, a finite pure simplicial complex of dimension $d$ whose geometric realisation is homeomorphic to $S^d$ and in which the link of every vertex is a combinatorial $(d-1)$-sphere. A \emph{triangulation} of the $d$-sphere is a combinatorial $d$-sphere, given by its $d$-simplices (\emph{chambers}); this is the piecewise-linear setting of \cite{planken2024colouring}, in which the dual complex of a triangulation is a CW complex. Its \emph{$i$-cells} are the faces with $i+1$ vertices and its \emph{1-skeleton} is the graph of vertices and $1$-cells. \emph{Subdividing} a chamber at a new vertex $v$ replaces it by the $d+1$ chambers spanned by $v$ and its facets; a \emph{subdivision} of $C$ subdivides a set of chambers, the \emph{maximal subdivision} all of them.
\end{definition}

\begin{theorem}[Planken, Theorem 1 \cite{planken2024colouring}]\label{skeleton}
Let $d \ge 2$ and let $C$ be a triangulation of $S^d$. The 1-skeleton of $C$ is properly $(d+2)$-colourable if and only if $C$ has a subdivision in which every $(d-2)$-cell is incident with a number of $(d-1)$-cells divisible by three. For $d = 3$ both are equivalent to the maximal subdivision of $C$ having a $2$-edge-colouring with no monochromatic $2$-cell.
\end{theorem}

