\section*{Challenge 102: The Full Rank Condition for Sparse Random Matrices}
\refstepcounter{section}

\begin{definition}[The random matrix model]
Let $d$ and $k \ge 3$ be probability distributions on the integers (\emph{degree laws}) with $\mathbb E[d^{2+\eta}] + \mathbb E[k^{2+\eta}] < \infty$ for some $\eta > 0$, and let $\mathfrak d$, $\mathfrak k$ be the gcds of their supports. The matrix $\mathbb A = \mathbb A_n(d,k,\chi)$ over a finite field $\mathbb F$ of order $q$ coprime to $\mathfrak d$ has $n$ columns and $m \sim \mathrm{Po}(\mathbb E[d]\, n/\mathbb E[k])$ rows; its nonzero pattern is a uniformly random simple bipartite graph with column degrees drawn from $d$ and row degrees from $k$, and its nonzero entries are independent with law $\chi$ on $\mathbb F \setminus \{0\}$. The function $\Phi$ of the paper's (1.2) is built from the generating functions of $d$ and $k$.
\end{definition}

\begin{theorem}[Coja-Oghlan, Gao, Hahn-Klimroth, Lee, M\"uller, Rolvien, Theorem 1.1 \cite{cojaoghlan2021fullrank}]\label{fullrank}
If $\Phi(z) < \Phi(0)$ for all $0 < z \le 1$, then $\mathbb A_n(d,k,\chi)$ has full row rank over $\mathbb F$ with high probability as $n \to \infty$ along multiples of $\mathfrak k$.
\end{theorem}

\paragraph{Formalisation notes.} A degree law is a probability distribution on $\N$ with finite second moment; the $(2+\eta)$-moment bounds are hypotheses of the theorem, $k$ is supported on $\{3,4,\dots\}$, and the gcds $\mathfrak d$, $\mathfrak k$ of the supports are characterised by their divisibility properties. With $D$ and $K$ the probability generating functions of $d$ and $k$, the function of (1.2) is $\Phi(z) = D\ew{1 - K'(z)/\mathbb E[k]} - \frac{\mathbb E[d]}{\mathbb E[k]}\ew{1 - K(z) - (1-z)K'(z)}$, and the hypothesis is $\Phi(z) < \Phi(0)$ for $0 < z \le 1$. The degrees are sampled as in Section 1.2.1 of \cite{cojaoghlan2021fullrank}: $d_1, \dots, d_n$ independent with law $d$, an independent row count $m \sim \mathrm{Po}(\mathbb E[d]\, n/\mathbb E[k])$, and $k_1, \dots, k_m$ independent with law $k$, conditioned on $\sum_i d_i = \sum_j k_j$ (the paper's (1.1)) and on the existence of a simple bipartite graph with these degrees; the nonzero pattern of $\mathbb A$ is then a uniformly random such graph, and the entries on its edges are independent with law $\chi$. Conditioning on an event of probability zero returns the unconditioned law and a uniform choice from an empty set of graphs returns the empty graph; neither junk value occurs once the conditioning event has positive probability, which by \cite{cojaoghlan2021fullrank} is of order $\Omega(n^{-1/2})$ when $\mathfrak k \mid n$, whence the limit along multiples of $\mathfrak k$. Since the number of rows is random, a sample is a pair (row count, matrix). Full row rank means that every linear system $\mathbb A x = y$ is solvable, which is equivalent to $\operatorname{rank} \mathbb A = m$. The field is an arbitrary finite field of order $q$; taking for $\chi$ the point mass at $1$ gives the zero-one biadjacency matrix, the case recorded as a corollary.

