\section*{Challenge 103: The Dimension of Co-Sparse Random Bipartite Graph Orders}
\refstepcounter{section}

\begin{definition}[Random bipartite graph orders, dimension]
For the random bipartite graph $B(n,n,p)$ on parts $A = [n]$ and $B = \{n+1,\dots,2n\}$, in which each pair $ab$ with $a \in A$, $b \in B$ is an edge independently with probability $p$, the order $P_{B(n,n,p)}$ has $a \le b$ exactly when $ab$ is an edge. The \emph{dimension} of a poset is the least number of linear extensions whose intersection is the poset.
\end{definition}

\begin{theorem}[Gao--Kumar, Theorem 9 \cite{gaokumar2025dimension}]\label{dimension}
Let $q = 1-p$. (a) If $q = O(1/n)$ and $q = \omega(1/n^2)$, then asymptotically almost surely $\dim P_{B(n,n,p)} = \Theta(n^2 q)$ and $n - \dim P_{B(n,n,p)} = \Omega(n)$. (b) If $q = \omega(1/n)$ and $q \le n^{-1+1/7}$, then asymptotically almost surely $\dim P_{B(n,n,p)} = (1-o(1))\,n$.
\end{theorem}

\paragraph{Formalisation notes.} The vertex set of $B(n,n,p)$ is $\{0, \dots, 2n-1\}$, with $A$ the first $n$ and $B$ the last $n$ vertices; it is the random graph in which each pair is an edge independently with probability $p$ between the parts and $0$ inside a part. The order of a graph on $\{0, \dots, N-1\}$ is the reflexive--transitive closure of the relation $i < j$, $ij \in E$; since $A$ lies below $B$, for a bipartite graph this is the bipartite order of the definition above. The dimension is the least size of a realiser, with the junk value $0$ when no realiser exists, which never happens for a finite poset. Here $p = p(n) \in [0,1]$ is a sequence and $q = 1 - p$: $q = O(1/n)$ means $q \le C/n$ for some $C$ and all large $n$, $q = \omega(1/n^2)$ means $n^2 q \to \infty$, $q = \omega(1/n)$ means $nq \to \infty$, and $q \le n^{-1+1/7}$ is required for all large $n$. ``Asymptotically almost surely'' means with probability tending to $1$: part (a) asserts constants $c_1, c_2, c > 0$, which may depend on the sequence $p$, with $\Pr\ev{c_1 n^2 q \le \dim P_{B(n,n,p)} \le c_2 n^2 q} \to 1$ and $\Pr\ev{\dim P_{B(n,n,p)} \le (1-c)\,n} \to 1$, and part (b) asserts $\Pr\ev{(1-\varepsilon)\,n \le \dim P_{B(n,n,p)} \le (1+\varepsilon)\,n} \to 1$ for every $\varepsilon > 0$.

