\section*{Challenge 104: Sandwiching Random Regular Graphs between Erd\H{o}s--R\'enyi Graphs}
\refstepcounter{section}

\begin{definition}[The models, sandwich couplings]
$G(n,d)$ is the uniformly random $d$-regular simple graph on $[n]$ ($dn$ even), $G(n,p)$ the Erd\H{o}s--R\'enyi graph. A \emph{sandwich coupling} is a joint distribution of $G_* \sim G(n,p_*)$, $G \sim G(n,d)$, $G^* \sim G(n,p^*)$ with $G_* \subseteq G \subseteq G^*$ with probability $1-o(1)$.
\end{definition}

\begin{theorem}[Gao--Isaev--P\'erez-Gim\'enez, Theorem 1.5 \cite{gaoisaevperezgimenez2025sandwich}]\label{sandwich}
Let $d = d(n)$ with $dn$ even and $d \le n-1$. (a) If $d = n - O(\log^4 n)$ there are $p_*, p^* = (1+o(1))d/n$ and a sandwich coupling. (b) If $d \gg \log n$ and $d = O(\log^4 n)$ the same holds with $p_* = (1-o(1))d/n$ and $p^* = (8+o(1))d/n$. (c) If $d = o(\log n)$, then for every fixed $\varepsilon > 0$ there is a coupling of $G(n,d)$ and $G(n,p_n)$ under which $G(n,d) \subseteq G(n,p_n)$ with probability $1 - o(1)$, where $p_n = (1+\varepsilon)\log n / n$ for even $n$ and $p_n = (2+\varepsilon)\log n / n$ for odd $n$. (d) For every $c > 0$ there is $C > 0$ such that, whenever $d \leq c \log n$ for all large $n$, $G(n,d)$ embeds into $G(n, C\log n / n)$ with probability $1 - o(1)$.
\end{theorem}

Part (a) resolves the Kim--Vu sandwich conjecture in the regime of very large degrees; the paper's constructions use the configuration model and unions of perfect matchings.

\paragraph{Formalisation notes.} The degree $d = d(n)$ is a sequence, and the hypothesis $dn$ even, $d \le n-1$ is stated as: for every $n$, some simple graph on $[n]$ is $d(n)$-regular. $G(n,d)$ is the uniform distribution on the $d$-regular simple graphs on $[n]$ (with the empty graph as junk value when there is none, which the hypothesis excludes), and $G(n,p)$ is defined for every real $p$, a value outside $[0,1]$ being clamped to that interval. A coupling is, for each $n$, a joint distribution of two or three random graphs on $[n]$ with the prescribed marginals, and ``with probability $1 - o(1)$'' means that the probability of the event $G_* \subseteq G \subseteq G^*$ (or $G \subseteq G^*$) under these couplings tends to $1$. The asymptotic conditions are limits: $p = (c + o(1))\,d/n$ means $p/(d/n) \to c$, $d \gg \log n$ means $d / \log n \to \infty$, $d = o(\log n)$ means $d / \log n \to 0$, and $d = O(\log^4 n)$, $d = n - O(\log^4 n)$ and $d \le c \log n$ mean that $d \le C \log^4 n$, $n - d \le C \log^4 n$ (for some $C$) and $d \le c \log n$ hold for all large $n$. In (d) the constant $C$ depends only on $c$, not on the sequence $d$.

