\section*{Challenge 106: Connectivity Thresholds of the Pre- and Post-Positional Semi-Random Processes}
\refstepcounter{section}

\begin{definition}[The two processes]
In the \emph{post-positional} semi-random process a vertex $u_t$ is offered uniformly at random and the player then chooses $v_t$; in the \emph{pre-positional} process the player chooses $v_t$ first and $u_t$ is then uniform and independent of $v_t$. In both, the edge $u_t v_t$ is added in round $t$ (loops and multiple edges may arise; properties concern the underlying simple graph).
\end{definition}

\begin{theorem}[Gao--Koerts, Theorem 1.1 \cite{gaokoerts2023positional}]\label{positional}
For every fixed $k \ge 1$ there is $\alpha_k \in \mathbb R$ such that for every $\varepsilon > 0$: no strategy in either process builds a $k$-connected graph within $(\alpha_k - \varepsilon)n$ rounds asymptotically almost surely, while strategies in both processes build a $k$-connected graph within $(\alpha_k+\varepsilon)n$ rounds asymptotically almost surely. Here $\alpha_1 = 1$ and, for $k \ge 2$, $\alpha_k$ is the constant of Wormald's min-degree process.
\end{theorem}

\paragraph{Formalisation notes.} The vertex set is $[n]$ with $n \ge 1$. Strategies are randomised and may depend on the whole history: in round $t$ the post-positional player draws $v_t$ from a distribution depending on $u_1, v_1, \dots, u_{t-1}, v_{t-1}$ and $u_t$, the pre-positional player from one depending on $u_1, v_1, \dots, u_{t-1}, v_{t-1}$ only. A graph is $k$-connected if it is connected and stays connected after deleting any set of fewer than $k$ vertices; for fixed $k$ and large $n$ this agrees with the usual definition, which also asks for more than $k$ vertices. ``Within $T$ rounds'' is read as ``after $\lfloor T \rfloor$ rounds'', which is equivalent because $k$-connectivity is preserved by adding edges. The lower bound is formalised as: for every sequence of strategies $(S_n)$, in either process, the probability that the graph on $[n]$ after $\lfloor(\alpha_k-\varepsilon)n\rfloor$ rounds is $k$-connected tends to $0$; the upper bound as the existence, in each process, of a sequence of strategies for which this probability after $\lfloor(\alpha_k+\varepsilon)n\rfloor$ rounds tends to $1$. The same $\alpha_k$ serves both processes, and only its existence is formalised, not its values.

