\end{thebibliography}

\section*{Challenge 107: Embedding Theorems for Random Graphs with Specified Degrees}
\refstepcounter{section}

\begin{definition}[The models]
For a symmetric matrix $W \in [0,1]^{[n]\times[n]}$, $G(n,W)$ is the random graph in which each pair $jk$ is an edge independently with probability $W_{jk}$; for a realisable degree sequence $d$, $G(n,d)$ is the uniformly random simple graph with degree sequence $d$. Write $\Delta(d)$, $\delta(d)$ for the maximum and minimum degree, $\|d\|_1 = \sum_i d_i$, and $J(d)$ for the sum of the $\Delta(d)$ largest degrees; $P(d)$ is the symmetric matrix of the paper's Definition 1.6 and $f(x) = 1 - e^{-x}$.
\end{definition}

\begin{theorem}[Gao--Ohapkin, Theorem 1.8 \cite{gaoohapkin2023embedding}]\label{embedding}
Let $d = d(n)$ be realisable with $J(d) = o(\|d\|_1)$ and $\delta(d) \gg \log n$. Then there are $\varepsilon = \varepsilon(n) = o(1)$ and couplings $(G_L, G)$ with $G_L \sim G(n,W)$, $W = (1-\varepsilon) f(P(d))$, and $G \sim G(n,d)$, such that $G_L \subseteq G$ with probability $1-o(1)$.
\end{theorem}

\paragraph{Formalisation notes.} The vertex set is $[n]$ for every $n \in \N$, and $d = d(n)$ is a degree sequence on $[n]$ for each $n$. The matrix of Definition 1.6 has entries $P(d)_{jk} = d_j d_k/(\|d\|_1 + d_j d_k)$ for $j \ne k$ and $P(d)_{jj} = 0$, and $f$ is applied entrywise. In $G(n,W)$ the pair $jk$ with $j < k$ is an edge with probability $W_{jk}$ clamped to $[0,1]$, which is $W_{jk}$ for the matrices that occur; $G(n,d)$ is the point mass at the empty graph when $d$ is not realisable, a case the hypotheses exclude. A coupling is a joint law of $(G_L, G)$ with the two prescribed marginals, and the conclusion is $\Pr(G_L \subseteq G) \to 1$. The hypotheses read $J(d(n))/\|d(n)\|_1 \to 0$ and $\delta(d(n))/\log n \to \infty$, where division by $0$ and $\log 0 = \log 1 = 0$ give the value $0$; this affects only finitely many $n$, since $\delta(d) \gg \log n$ forces $\|d(n)\|_1 > 0$ for large $n$. Realisability is assumed for every $n$ rather than for all large $n$. The paper asserts only $\varepsilon = o(1)$; the formal statement also requires $\varepsilon(n) \in [0,1]$, so that $W$ is a matrix of probabilities, which is no loss of generality by the nesting property of $G(n,W)$ (Section 1.2 of \cite{gaoohapkin2023embedding}).

