\section*{Challenge 108: Hamiltonian Cycles in the Semi-Random Graph Process in Fewer than $2n$ Rounds}
\refstepcounter{section}

\begin{definition}[The process and its Hamiltonian constant]
In round $t$ of the semi-random graph process a vertex $u_t \in [n]$ is offered uniformly at random, the online algorithm answers with a vertex $v_t \ne u_t$, and the edge $u_t v_t$ is added. For an increasing property $\mathcal P$, $m_{\mathcal P}(S,q,n)$ is the least number of rounds after which strategy $S$ has produced $\mathcal P$ with probability at least $q$, and $C_{\mathcal P}$ is the limit as $q \to 1^-$ of $\limsup_n \inf_S m_{\mathcal P}(S,q,n)/n$.
\end{definition}

\begin{theorem}[Frieze--Gao--MacRury--Pra\l{}at--Sorkin, Theorem 1.1 \cite{friezegaomacruryralatsorkin2023hamiltonian}]\label{ham2n}
$C_{\mathrm{HAM}} \le 1.81701$: for every $q < 1$ and $\varepsilon > 0$ and all large $n$, some strategy builds a Hamiltonian cycle on $[n]$ with probability at least $q$ within $(1.81701+\varepsilon)n$ rounds.
\end{theorem}

\paragraph{Formalisation notes.} A strategy assigns to each history $(u_1, v_1, \dots, u_{t-1}, v_{t-1})$ and offered vertex $u_t$ a probability distribution on $[n] \setminus \{u_t\}$ from which $v_t$ is drawn; it may use the whole history but not the future offers. The graph $G_t$ is the simple graph underlying the multigraph of the first $t$ edges (repeated edges are discarded, which does not affect Hamiltonicity), and $\mathrm{HAM}$ is Hamiltonicity in the sense of Mathlib's \texttt{SimpleGraph.IsHamiltonian}. Probabilities are taken in $[0,\infty]$, $m_{\mathcal P}(S,q,n) = \infty$ if no round reaches probability $q$, and $C_{\mathcal P} \in [0,\infty]$. The $\limsup$ runs over $n \ge 2$: on one vertex no answer $v_t \ne u_t$ exists, so there is no strategy, and a single term does not change the $\limsup$. Since $\limsup_n m_{\mathcal P}(q,n)/n$ is non-decreasing in $q$, $C_{\mathcal P}$ is defined as its supremum over $0 < q < 1$, which is the left limit at $q = 1$. The constant $1.81701$ is the bound printed in Theorem 1.1 of \cite{friezegaomacruryralatsorkin2023hamiltonian}; the abstract and Section 2.7 of the paper give the slightly sharper bound $1.81696$.

